/* Real MCP authoring surface discovery/resources/verify/run/canonical identity. */
#define _POSIX_C_SOURCE 200809L
#include "../runtime/apx_runtime.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
static unsigned checks;
static void require(int ok,const char *message){checks++;if(!ok){fprintf(stderr,"MCP compact authoring FAIL: %s\n",message);exit(1);}}
static char *readall(const char *path){FILE *f=fopen(path,"rb");require(f!=NULL,"open MCP response");require(!fseek(f,0,SEEK_END),"seek MCP response");long n=ftell(f);require(n>=0&&n<8*1024*1024,"bounded MCP response");rewind(f);char *text=calloc(1,(size_t)n+1);require(text&&fread(text,1,(size_t)n,f)==(size_t)n&&!fclose(f),"read MCP response");return text;}
static ApxValue *response(const char *all,int id){const char *p=all;while(*p){const char *end=strchr(p,'\n');require(end!=NULL,"newline-delimited MCP");ApxValue *row=apx_json_parse(p,(size_t)(end-p));require(row!=NULL,"valid MCP JSON");if(apx_json_integer(apx_json_get(row,"id"))==id){require(!apx_json_get(row,"error"),"no JSON-RPC error");return apx_json_get(row,"result");}p=end+1;}require(0,"missing expected reply");return NULL;}
static ApxValue *structured(const char *all,int id,int ok){ApxValue *result=response(all,id),*value=apx_json_get(result,"structuredContent");const char *status=apx_json_string(apx_json_get(value,"status"));require(status&&!strcmp(status,ok?"ok":"error"),"expected native tool status");require(apx_json_integer(apx_json_get(result,"isError"))==!ok,"MCP error flag matches status");return value;}
static void description_tests(const char *all){
    ApxValue *tools=apx_json_get(response(all,8),"tools");
    require(apx_json_length(tools)==10,"complete tool description surface");
    const char *verify=NULL,*check=NULL,*format=NULL;
    for(size_t i=0;i<apx_json_length(tools);i++){
        ApxValue *tool=apx_json_item(tools,i);
        const char *name=apx_json_string(apx_json_get(tool,"name"));
        const char *description=apx_json_string(apx_json_get(tool,"description"));
        require(name&&description,"tool names and descriptions are strings");
        if(!strcmp(name,"apodexis_verify"))verify=description;
        else if(!strcmp(name,"apodexis_check"))check=description;
        else if(!strcmp(name,"apodexis_format"))format=description;
    }
    require(verify&&strstr(verify,"row.id")&&strstr(verify,"rows[index]"),"verify description teaches postfix reads");
    require(verify&&strstr(verify,"P out value")&&strstr(verify,"S out (push out value)"),"verify description teaches both builder spellings");
    require(verify&&strstr(verify,"inferred locals")&&strstr(verify,"signatures")&&strstr(verify,"empty/variant"),"verify description preserves inference boundaries");
    require(verify&&strstr(verify,"prefix canonical")&&!strstr(verify,"Expressions are prefix calls"),"verify distinguishes ordinary calls from postfix sugar");
    require(check&&strstr(check,"P statements"),"check description recognizes P statements");
    require(format&&strstr(format,"prefix canonical")&&strstr(format,"Postfix")&&strstr(format,"P writeback"),"format description explains canonical expansion");
}
int main(void){const char *short_source="M authoring\nT Row struct\n  id:i64\nF main rows:[Row]->[i64]\n  L out (buf i64 (# rows))\n  E row rows\n    P out row.id\n  R (finish out)\nX sample\n  A (= (main [(Row id=3)]) [3])\n";
    const char *prefix="M authoring\nT Row struct\n  id:i64\nF main rows:[Row]->[i64]\n  L out (buf i64 (# rows))\n  E row rows\n    S out (push out (. row id))\n  R (finish out)\nX sample\n  A (= (main [(Row id=3)]) [3])\n";
    const char *bad="M bad\nT Row struct\n  id:i64\nF main rows:[Row]->i64\n  R rows[0].missing\n";
    ApxValue *value=apx_string(short_source,(int64_t)strlen(short_source));char *s=apx_json_encode(value);value=apx_string(prefix,(int64_t)strlen(prefix));char *p=apx_json_encode(value);value=apx_string(bad,(int64_t)strlen(bad));char *b=apx_json_encode(value);require(s&&p&&b,"encoded source arguments");
    char payload[65537];int n=snprintf(payload,sizeof payload,"{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\"}\n{\"jsonrpc\":\"2.0\",\"method\":\"notifications/initialized\"}\n{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"resources/read\",\"params\":{\"uri\":\"apodexis://spec/language\"}}\n{\"jsonrpc\":\"2.0\",\"id\":3,\"method\":\"tools/call\",\"params\":{\"name\":\"apodexis_verify\",\"arguments\":{\"source\":%s}}}\n{\"jsonrpc\":\"2.0\",\"id\":4,\"method\":\"tools/call\",\"params\":{\"name\":\"apodexis_run\",\"arguments\":{\"source\":%s,\"input\":[{\"id\":3},{\"id\":7}],\"limits\":{\"fuel\":1000000,\"max_input_bytes\":null,\"max_output_bytes\":null}}}}\n{\"jsonrpc\":\"2.0\",\"id\":5,\"method\":\"tools/call\",\"params\":{\"name\":\"apodexis_run\",\"arguments\":{\"source\":%s,\"input\":[{\"id\":3},{\"id\":7}],\"limits\":{\"fuel\":1000000,\"max_input_bytes\":null,\"max_output_bytes\":null}}}}\n{\"jsonrpc\":\"2.0\",\"id\":6,\"method\":\"tools/call\",\"params\":{\"name\":\"apodexis_check\",\"arguments\":{\"source\":%s}}}\n{\"jsonrpc\":\"2.0\",\"id\":7,\"method\":\"ping\"}\n{\"jsonrpc\":\"2.0\",\"id\":8,\"method\":\"tools/list\"}\n",s,s,p,b);require(n>0&&(size_t)n<sizeof payload,"bounded authoring transcript");free(s);free(p);free(b);apx_json_reset();char directory[]=".build/authoring-mcp-XXXXXX";require(mkdtemp(directory)!=NULL,"authoring MCP scratch");char input[4096],output[4096];snprintf(input,sizeof input,"%s/input",directory);snprintf(output,sizeof output,"%s/output",directory);FILE *f=fopen(input,"wb");require(f&&fwrite(payload,1,(size_t)n,f)==(size_t)n&&!fclose(f),"write transcript");fflush(NULL);pid_t pid=fork();require(pid>=0,"fork MCP");if(!pid){if(!freopen(input,"rb",stdin)||!freopen(output,"wb",stdout))_exit(126);execl("bin/apx-mcp","bin/apx-mcp",(char*)NULL);_exit(127);}int status;require(waitpid(pid,&status,0)==pid&&WIFEXITED(status)&&!WEXITSTATUS(status),"actual MCP process succeeds");char *all=readall(output);ApxValue *init=response(all,1);const char *instructions=apx_json_string(apx_json_get(init,"instructions"));require(instructions&&strstr(instructions,"row.id")&&strstr(instructions,"P out value"),"initialization advertises authoring forms");ApxValue *resource=response(all,2);const char *guide=apx_json_string(apx_json_get(apx_json_item(apx_json_get(resource,"contents"),0),"text"));require(guide&&strstr(guide,"rows[index]")&&strstr(guide,"P out value")&&strstr(guide,"prefix canonical"),"resource reference describes syntax/canonical policy");
    ApxValue *verified=structured(all,3,1);require(apx_json_length(apx_json_get(apx_json_get(verified,"test"),"tests"))==1,"source tests actually execute");const char *canonical=apx_json_string(apx_json_get(apx_json_get(apx_json_get(verified,"format"),"response"),"source"));require(canonical&&strstr(canonical,"S out (push out (. row id))"),"canonical output expands short surface");ApxValue *one=structured(all,4,1),*two=structured(all,5,1);const char *keys[]={"source_hash","contract_hash","output_hash","fuel_used","output"};for(size_t i=0;i<5;i++){char *a=apx_json_encode(apx_json_get(one,keys[i])),*z=apx_json_encode(apx_json_get(two,keys[i]));require(a&&z&&!strcmp(a,z),"short/prefix native execution record parity");free(a);free(z);}char *actual=apx_json_encode(apx_json_get(one,"output"));require(actual&&!strcmp(actual,"[3,7]")&&apx_json_integer(apx_json_get(one,"fuel_used"))==9,"native result and fuel correct");free(actual);ApxValue *failure=structured(all,6,0);ApxValue *diag=apx_json_item(apx_json_get(failure,"diagnostics"),0);require(!strcmp(apx_json_string(apx_json_get(diag,"code")),"N101"),"postfix field error remains structured");require(apx_json_integer(apx_json_get(apx_json_get(diag,"span"),"start_byte"))==(int64_t)(strstr(bad,"missing")-bad),"MCP error span uses authored bytes");require(response(all,7)!=NULL,"MCP responsive after rejection");description_tests(all);free(all);apx_json_reset();unlink(input);unlink(output);require(!rmdir(directory),"MCP scratch cleanup");printf("native compact authoring MCP: %u checks; discovery/resources/verify/run/hash/fuel/spans/recovery PASS\n",checks);return 0;}
